Rules.InvariantScript:
Set(gblBusy, true);
Set(gblError, {IsVisible: false, Title: "", Detail: ""});
Select(btnDoLoadApprovals);
Set(gblBusy, false)

IfError(
    ClearCollect(
        colApprovals,
        Filter(
        // Table2 carries the request rows. Table1 is a summary set, not the data.
        db_dq_sandbox.dquspGetPendingApprovals(
            {ActorUpn: gblActorUpn, ApprovalType: Blank()}
        ).ResultSets.Table2,
            !IsBlank(ApprovalId)
        )
    ),
    Set(gblError, {IsVisible: true, Title: "Could not load approvals", Detail: FirstError.Message})
)

Navigate(
    scrQueue,
    ScreenTransition.None,
    {locInAssignee: "", locInSeverity: "", locInOverdue: false, locInCluster: Blank()}
)

Set(gblBusy, true);
Set(gblError, {IsVisible: false, Title: "", Detail: ""});
IfError(
    Set(
        gblWriteResult,
        First(
            db_dq_sandbox.dquspApproveSuppression(
                {
                    ActorUpn: gblActorUpn,
                    SuppressionId: ThisItem.ApprovalId,
                    Approve: true,
                    Comment: Trim(txtAppComment.Text)
                }
            ).ResultSets.Table1
        )
    ),
    Set(gblError, {IsVisible: true, Title: "The approval was not recorded", Detail: FirstError.Message})
);
If(
    Upper(Coalesce(gblWriteResult.Outcome, "")) = "OK",
    Notify("Approved.", NotificationType.Success, 3000);
    RemoveIf(colApprovals, ApprovalId = ThisItem.ApprovalId),
    Notify(Coalesce(gblWriteResult.Message, "The approval was not recorded."), NotificationType.Error, 6000)
);
Set(gblBusy, false)

Set(gblBusy, true);
Set(gblError, {IsVisible: false, Title: "", Detail: ""});
IfError(
    Set(
        gblWriteResult,
        First(
            db_dq_sandbox.dquspApproveSuppression(
                {
                    ActorUpn: gblActorUpn,
                    SuppressionId: ThisItem.ApprovalId,
                    Approve: false,
                    Comment: Trim(txtAppComment.Text)
                }
            ).ResultSets.Table1
        )
    ),
    Set(gblError, {IsVisible: true, Title: "The rejection was not recorded", Detail: FirstError.Message})
);
If(
    Upper(Coalesce(gblWriteResult.Outcome, "")) = "OK",
    Notify("Rejected.", NotificationType.Success, 3000);
    RemoveIf(colApprovals, ApprovalId = ThisItem.ApprovalId),
    Notify(Coalesce(gblWriteResult.Message, "The rejection was not recorded."), NotificationType.Error, 6000)
);
Set(gblBusy, false)
